#!/usr/bin/env bash
# External monitoring test (#15), locally and in the CI `monitoring` job.
#
# Starts infra/monitoring with the configuration generated by configure.sh and checks:
# 1. Prometheus, rules and Alertmanager with a valid configuration;
# 2. the heartbeat (Watchdog) reaches the external receiver;
# 3. when a target goes down, the alert email arrives (EndpointDown);
# 4. when it comes back, the resolved email arrives.
#
# Usage, from the repository root: infra/monitoring/test/monitoring-test.sh
set -euo pipefail

root="$(cd "$(dirname "$0")/../.." && pwd)"
project=stellytics-monitortest
work=$(mktemp -d "${TMPDIR:-/tmp}/stellytics-monitortest.XXXXXX")
cp -R "$root/monitoring/." "$work/"
rm -rf "$work/test"
cat > "$work/monitoring.env" <<'EOT'
PORTAL_HOST=portal.invalid
INGEST_HOST=ingest.invalid
ALERT_EMAIL=ops@example.org
SMTP_SMARTHOST=mailpit:1025
SMTP_FROM=monitor@example.org
SMTP_REQUIRE_TLS=false
DEADMAN_URL=http://deadman:8080/ping
EOT
# A restrictive umask must not leave the config unreadable to nobody.
(umask 077; "$root/monitoring/configure.sh" "$work/monitoring.env" "$work" >/dev/null)
grep -q 'https://ingest.invalid/healthz/stack' "$work/prometheus/targets/endpoints.yml" || { echo "FAILED: missing the stack check target" >&2; exit 1; }
for path in prometheus/targets alertmanager; do
  [ -n "$(find "$work/$path" -maxdepth 0 -perm -0005)" ] || { echo "FAILED: $path is not readable by nobody with umask 077" >&2; exit 1; }
done
for path in prometheus/targets/endpoints.yml alertmanager/alertmanager.yml; do
  [ -n "$(find "$work/$path" -perm -0004)" ] || { echo "FAILED: $path is not readable by nobody with umask 077" >&2; exit 1; }
done

cat > "$work/prometheus/targets/endpoints.yml" <<'EOT'
- targets: ["http://target:8080/"]
  labels:
    component: portal
EOT
chmod -R a+rX "$work"

# The heartbeat must go out every 5 minutes: the external service warns
# when it stops arriving.
grep -A4 'alertname="Watchdog"' "$work/alertmanager/alertmanager.yml" | grep -q 'receiver: deadman' || { echo "FAILED: Watchdog without deadman" >&2; exit 1; }
grep -A4 'alertname="Watchdog"' "$work/alertmanager/alertmanager.yml" | grep -q 'repeat_interval: 5m' || { echo "FAILED: Watchdog without 5m" >&2; exit 1; }

export PROMETHEUS_PORT=19090 ALERTMANAGER_PORT=19093 MAILPIT_TEST_PORT=18025
compose() { docker compose -p "$project" -f "$work/compose.yaml" -f "$root/monitoring/test/monitoring-test.yaml" "$@"; }

cleanup() {
  status=$?
  if [ "$status" -ne 0 ]; then compose logs --tail 60 prometheus alertmanager >&2 || true; fi
  compose down -v --remove-orphans >/dev/null 2>&1 || true
  rm -rf "$work"
  exit "$status"
}
trap cleanup EXIT
fail() { echo "FAILED: $*" >&2; exit 1; }
ok() { echo "ok: $*"; }
wait_for() { # seconds, description, command
  local limit=$1 what=$2; shift 2
  for _ in $(seq 1 "$limit"); do "$@" && return 0; sleep 1; done
  fail "$what (waited ${limit}s)"
}

compose up -d --wait

# 1. Valid configuration and tested rules (promtool test rules).
compose exec -T prometheus promtool check config /etc/prometheus/prometheus.yml >/dev/null
docker run --rm -v "$root/monitoring:/m:ro" -w /m/test --entrypoint promtool \
  prom/prometheus:v3.15.1@sha256:fa3302279710be2f21a8301ec17a8b4f2301fd829bd113839b3b6b02b6f191a2 \
  test rules alerts.test.yml >/dev/null
compose exec -T alertmanager amtool check-config /etc/alertmanager/alertmanager.yml >/dev/null
ok "Prometheus and Alertmanager configuration; rules and heartbeat interval tested"

query() { curl -fsS --get "http://127.0.0.1:19090/api/v1/query" --data-urlencode "query=$1" | python3 -c 'import sys,json; r=json.load(sys.stdin)["data"]["result"]; print(r[0]["value"][1] if r else "")'; }
probe_is() { [ "$(query 'probe_success{component="portal"}')" = "$1" ]; }
wait_for 90 "the target did not turn green in Prometheus" probe_is 1
ok "the blackbox tests the target"

# 2. Heartbeat.
deadman_called() { compose logs --no-color deadman 2>/dev/null | grep -q '"uri":"/ping"'; }
wait_for 90 "the Watchdog did not reach the heartbeat receiver" deadman_called
ok "heartbeat reaches the external receiver"

# 3. Target down: alert email.
mail_with() { curl -fsS "http://127.0.0.1:18025/api/v1/search?query=$(python3 -c 'import sys,urllib.parse; print(urllib.parse.quote(sys.argv[1]))' "$1")" | python3 -c 'import sys,json; sys.exit(0 if json.load(sys.stdin)["messages_count"] > 0 else 1)'; }
compose stop target >/dev/null
wait_for 60 "Prometheus did not see the target go down" probe_is 0
wait_for 180 "the alert email did not arrive" mail_with 'subject:"[FIRING:1] EndpointDown"'
mail_with 'portal is down' || fail "the alert email does not say which component went down"
ok "email alert when the target goes down"

# 4. Target back: resolved email.
compose start target >/dev/null
wait_for 60 "Prometheus did not see the target come back" probe_is 1
wait_for 180 "the resolved email did not arrive" mail_with 'subject:"[RESOLVED] EndpointDown"'
ok "resolved email when the target comes back"

echo "monitoring: all good"
